// Разбор ICS без библиотек: формат построчный, а тянуть зависимость
// ради него — лишнее (§2 CLAUDE.md).
//
// ЧЕСТНЫЙ ОТКАЗ ВМЕСТО ПУСТОГО СПИСКА. Календарь не ответил — это НЕ
// «сегодня ничего нет». Разница видна владельцу: пустой день и
// недоступный календарь — разные сообщения.
const input = $input.first().json;
const body = typeof input.data === 'string' ? input.data : (input.body || '');
if (!body || input.error) {
  return [{ json: { ok: false, reason: 'календарь недоступен', events: [] } }];
}

const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Moscow' });
const unfolded = body.replace(/\r\n[ \t]/g, '').split(/\r?\n/);
const events = [];
let current = null;
for (const line of unfolded) {
  if (line === 'BEGIN:VEVENT') { current = {}; continue; }
  if (line === 'END:VEVENT') {
    if (current && current.date === today) {
      events.push({ time: current.time || '', summary: current.summary || '(без названия)' });
    }
    current = null;
    continue;
  }
  if (!current) continue;
  const colon = line.indexOf(':');
  if (colon < 0) continue;
  const name = line.slice(0, colon).split(';')[0];
  const value = line.slice(colon + 1);
  if (name === 'SUMMARY') current.summary = value;
  if (name === 'DTSTART') {
    current.date = `${value.slice(0, 4)}-${value.slice(4, 6)}-${value.slice(6, 8)}`;
    current.time = value.length > 8 ? `${value.slice(9, 11)}:${value.slice(11, 13)}` : '';
  }
}
events.sort((a, b) => a.time.localeCompare(b.time));
return [{ json: { ok: true, date: today, events } }];
